(7481715, 1190129, 163081, '<td valign="top">What a nice portal and door. The image is not sharp.</td>', 'What a nice portal and door. The image is not sharp.', '2016-11-09 00:18:14.000000', NULL, 1),
(7481747, 1190309, 24744, '<td valign="top">Not fond of the halos around the gate posts.</td>', 'Not fond of the halos around the gate posts.', '2016-11-09 02:44:50.000000', NULL, 1),
(7481748, 1190111, 24744, '<td valign="top">Would have been nice to have the floor boards perfectly in line with the bottom of the frame, and the verticals on the door vertical.</td>', 'Would have been nice to have the floor boards perfectly in line with the bottom of the frame, and the verticals on the door vertical.', '2016-11-09 02:46:21.000000', NULL, 1),
(7481749, 1190304, 24744, '<td valign="top">Would have preferred if the verticals were exactly vertical, since they''re so close to it with just a tiny bit of downwards tilting perspective, which becomes distracting.  Also a bit of a sharpening halo along the edges of the flagstones.</td>', 'Would have preferred if the verticals were exactly vertical, since they''re so close to it with just a tiny bit of downwards tilting perspective, which becomes distracting.  Also a bit of a sharpening halo along the edges of the flagstones.', '2016-11-09 02:48:12.000000', NULL, 1),
(7481750, 1190350, 24744, '<td valign="top">In a shot that''s so geometrically driven, having the blinds just off-horizontal is distracting.  Also seems like excessive noise reduction evident around the lock and handle especially.</td>', 'In a shot that''s so geometrically driven, having the blinds just off-horizontal is distracting.  Also seems like excessive noise reduction evident around the lock and handle especially.', '2016-11-09 02:49:36.000000', NULL, 1),
(7481751, 1190344, 24744, '<td valign="top">You''ve made rather a mess of the cloning around the clouds above the gate post, very visible clone marks there.</td>', 'You''ve made rather a mess of the cloning around the clouds above the gate post, very visible clone marks there.', '2016-11-09 02:50:56.000000', NULL, 1),
(7481752, 1190347, 24744, '<td valign="top">A little more depth of field would have allowed the top edge of the handle to be sharp, which would have improved this image.</td>', 'A little more depth of field would have allowed the top edge of the handle to be sharp, which would have improved this image.', '2016-11-09 02:51:55.000000', NULL, 1),
(7481753, 1190333, 24744, '<td valign="top">Such a textured subject would have benefitted from being sharp throughout more of the frame.</td>', 'Such a textured subject would have benefitted from being sharp throughout more of the frame.', '2016-11-09 02:52:20.000000', NULL, 1),
(7481754, 1190366, 24744, '<td valign="top">Not fond of the radioactive violet glow shining through the cracks here.</td>', 'Not fond of the radioactive violet glow shining through the cracks here.', '2016-11-09 02:53:16.000000', NULL, 1),
(7481755, 1190294, 24744, '<td valign="top">Not fond of the strangely postprocessed background blur, the halos around the hills in the background don''t help the effect.  It would also have scored higher if the horizon had been straight.</td>', 'Not fond of the strangely postprocessed background blur, the halos around the hills in the background don''t help the effect.  It would also have scored higher if the horizon had been straight.', '2016-11-09 02:56:15.000000', NULL, 1),
(7481756, 1190240, 24744, '<td valign="top">For a stock-style shot like this, it would really help if the subjects were fully in focus.  The red halo around the key shows a bit of a clumsy cut-out, too.</td>', 'For a stock-style shot like this, it would really help if the subjects were fully in focus.  The red halo around the key shows a bit of a clumsy cut-out, too.', '2016-11-09 03:01:25.000000', NULL, 1),
