(7483277, 1190001, 12611, '<td valign="top">I like the light here. the drive by voters didn''t spend too much time, but it is worth a long look. Perhaps the brown is a bit too warm, and it might work better either with boosted shadows or the opposite way as a full silhouette.</td>', 'I like the light here. the drive by voters didn''t spend too much time, but it is worth a long look. Perhaps the brown is a bit too warm, and it might work better either with boosted shadows or the opposite way as a full silhouette.', '2016-11-20 08:06:28.000000', NULL, 0),
(7483309, 1190001, 37719, '<td valign="top">Love the concept of this photo.  I wish the processing was a bit different, but the thought process is spot on I think.</td>', 'Love the concept of this photo.  I wish the processing was a bit different, but the thought process is spot on I think.', '2016-11-20 17:04:46.000000', NULL, 0),
